private void handleNewApplyFlow(PermissionApplyFlowRuleContext context) {
    PermissionApplyClassifyVo classifyVo = context.getClassifyVo();

    // 只要有一条新申请 L3 → 走 L3 审批流（最长）
    List<RolePermissionVO> newApplyL3 = classifyVo.getNewApplyL3Permissions();
    if (CollectionUtils.isNotEmpty(newApplyL3)) {
        handleNewApplyL3Flow(context, newApplyL3);   // L3 内部再分 操作/查询
        return;
    }
    // 没有 L3 看 L2
    List<RolePermissionVO> newApplyL2 = classifyVo.getNewApplyL2Permissions();
    if (CollectionUtils.isNotEmpty(newApplyL2)) {
        handleNewApplyL2Flow(context, newApplyL2);
        return;
    }
    // 只剩 L1
    handleNewApplyL1Flow(context);
}
